function createPopupWindow(){ 
jQuery(function() { 
jQuery( "#dialog-confirm" ).dialog({ 
autoOpen: true, 
width : 500, 
show: { 
effect: "Bounce", 
duration:1000 
}, 

hide: { 
effect: "Explode", 
duration: 1000 
}, 
buttons: { 
"Send Mail": 
function() { 
sendMail(); 
}, 

Cancel: 
function() { 
jQuery( this ).dialog( "close" ); 
} 
} 
}); 
}); 
} 
